// ==UserScript==
// @name         掘金弹幕 - 论坛走动小人 Juejin Danmu
// @name:en      Juejin Danmu - Walking Characters
// @namespace    https://github.com/msg-wall/juejin
// @version      1.0.0
// @description  在掘金(juejin.cn)页面添加透明背景的走动小人/猫/狗/兔子，角色在页面底部走动并播报沸点、热榜、评论等消息，打造生动的弹幕墙效果。
// @description:en Add transparent walking characters (person/cat/dog/rabbit) on juejin.cn, they walk across your page and announce pins/hot/comments like a living danmaku wall.
// @author       msg-wall
// @match        *://juejin.cn/*
// @match        *://*.juejin.cn/*
// @run-at       document-idle
// @grant        none
// @license      MIT
// @icon         data:image/png;base64,
// ==/UserScript==

/**
 * 油猴脚本入口 - Tampermonkey Userscript Entry
 *
 * 工作方式：
 * 1. 将 character-renderer.js / message-wall-core.js / juejin-integration.js
 *    的内容直接内联打包（也可以从 CDN 加载）
 * 2. 因为 @grant none，所以脚本在页面上下文运行，直接可以访问 DOM / fetch
 *
 * 部署提示：
 * - 如果想远程加载最新代码，可以将下面的 INLINE 替换为 fetch+eval 或动态 <script>
 * - 这里为了离线可用，使用动态加载本地文件（调试）+ 生产版本用内联
 */

(function () {
  'use strict';

  if (window.__MSG_WALL_LOADED__) return;
  window.__MSG_WALL_LOADED__ = true;

  // ========= 配置 =========
  const CONFIG = {
    // 脚本源：本地文件调试路径（油猴中如果不是本地，会自动 fallback 到内联版本）
    devBase: null, // 例如 'file:///d:/2workspace/codex/juejin3/' 用于本地调试
    useCDN: false, // 如发布到 CDN 可改为 true
    cdnBase: 'https://cdn.jsdelivr.net/gh/your/repo@main/',

    // 默认引擎参数
    engine: {
      characterCount: 16,
      characterTypeRatio: { person: 0.6, cat: 0.15, dog: 0.15, rabbit: 0.1 },
      floorRatio: 0.93,
      zIndex: 99999,
      opacity: 1,
      messageInterval: 1500,
      messageDuration: 7500,
      showFloorLine: false,
    },
    panelPosition: 'top-right',
  };

  // ========= 内联版本的 fallback（防止本地路径不可用） =========
  // 生产版本应当将三个文件内容内联到这里。此处为了保证你能直接运行，
  // 使用 eval + 动态加载的方式，同时也提供了一个极简 fallback。

  const INLINE_FALLBACK = `
    // 如果外部加载失败，使用最小化版本启动（你也可以把整个三个文件的内容粘贴到这里）
    console.warn('[MessageWall] external load failed, using minimal fallback');
    window.CharacterRenderer = window.CharacterRenderer || {
      drawCharacter: function(ctx,x,y,type,dir,f,s,o){
        ctx.save();
        ctx.translate(x,y-30*s);
        ctx.fillStyle = o && o.color || '#3498DB';
        ctx.fillRect(0,10*s,20*s,20*s);
        ctx.fillStyle = o && o.skinColor || '#F5D5C8';
        ctx.beginPath();
        ctx.arc(10*s, 5*s, 10*s, 0, Math.PI*2);
        ctx.fill();
        ctx.fillStyle = '#2C3E50';
        ctx.fillRect(2*s, 30*s, 6*s, 10*s);
        ctx.fillRect(12*s, 30*s, 6*s, 10*s);
        ctx.restore();
        return {width:20*s,height:40*s};
      },
      generateRandomOptions: function(){ return { color: '#'+Math.floor(Math.random()*0xFFFFFF).toString(16).padStart(6,'0') }; }
    };
  `;

  // ========= 加载外部脚本 =========
  function loadScript(src) {
    return new Promise((resolve, reject) => {
      const s = document.createElement('script');
      s.src = src;
      s.onload = () => resolve();
      s.onerror = (e) => reject(e);
      document.head.appendChild(s);
      // 10秒超时
      setTimeout(() => reject(new Error('timeout: ' + src)), 10000);
    });
  }

  async function loadDependencies() {
    // 策略1: 本地调试路径
    if (CONFIG.devBase) {
      try {
        await Promise.all([
          loadScript(CONFIG.devBase + 'character-renderer.js'),
          loadScript(CONFIG.devBase + 'message-wall-core.js'),
          loadScript(CONFIG.devBase + 'juejin-integration.js'),
        ]);
        return true;
      } catch (e) {
        console.warn('[MessageWall] devBase load failed:', e);
      }
    }
    // 策略2: CDN
    if (CONFIG.useCDN && CONFIG.cdnBase) {
      try {
        await Promise.all([
          loadScript(CONFIG.cdnBase + 'character-renderer.js'),
          loadScript(CONFIG.cdnBase + 'message-wall-core.js'),
          loadScript(CONFIG.cdnBase + 'juejin-integration.js'),
        ]);
        return true;
      } catch (e) {
        console.warn('[MessageWall] CDN load failed:', e);
      }
    }
    // 策略3: 使用 Blob URL 方式，将油猴头部 @require 的内容注入（如果有的话）
    // 策略4: fallback 内联最小版本
    try { (0, eval)(INLINE_FALLBACK); } catch (e) { console.error(e); }
    return false;
  }

  // ========= 也尝试从当前路径查找（当用户直接打开本地 html 时兼容） =========
  async function tryLoadFromSameOrigin() {
    // 如果 location 是 file:// 或本地 http，尝试相对路径
    if (!location.hostname.includes('juejin.cn') || location.protocol === 'file:') {
      try {
        await Promise.all([
          loadScript('./character-renderer.js'),
          loadScript('./message-wall-core.js'),
          loadScript('./juejin-integration.js'),
        ]);
        return true;
      } catch (_) {
        return false;
      }
    }
    return false;
  }

  // ========= 启动主流程 =========
  async function boot() {
    // 在 juejin.cn 上，先用 devBase / CDN。否则尝试相对路径。
    const onJuejin = location.hostname.includes('juejin.cn');
    let loaded = false;
    if (onJuejin) {
      loaded = await loadDependencies();
    } else {
      loaded = await tryLoadFromSameOrigin();
    }

    // 兜底：如果 CharacterRenderer 仍不存在，用内联 fallback
    if (!window.CharacterRenderer) {
      try { (0, eval)(INLINE_FALLBACK); } catch (e) { console.error(e); }
    }
    if (!window.MessageWallCore) {
      // 构造一个最小引擎
      window.MessageWallCore = buildMinimalEngine();
    }
    if (!window.JuejinMessageWall) {
      window.JuejinMessageWall = buildMinimalIntegration();
    }

    try {
      startApp();
    } catch (e) {
      console.error('[MessageWall] boot error:', e);
    }
  }

  function startApp() {
    const { MessageWallEngine } = window.MessageWallCore;
    const { JuejinMessageProvider, ControlPanel, attachBubbleInteraction } = window.JuejinMessageWall;

    const provider = new JuejinMessageProvider({ sources: ['pin', 'article', 'comment'] });

    const engine = new MessageWallEngine(document.body, {
      ...CONFIG.engine,
      onMessageRequest: () => provider.getMessageSync(),
    });

    engine.start();

    // 后台异步填充真实的掘金消息
    provider._ensurePoolFilled && provider._ensurePoolFilled();
    setInterval(() => provider._ensurePoolFilled && provider._ensurePoolFilled(), 45_000);

    // 面板
    const panel = new ControlPanel(engine, provider, { position: CONFIG.panelPosition });

    // 气泡悬停交互：鼠标悬停显示详情，点击跳转对应页面
    let bubbleInteraction = null;
    if (typeof attachBubbleInteraction === 'function') {
      bubbleInteraction = attachBubbleInteraction(engine);
    }

    // 监听关闭事件
    window.addEventListener('msgwall:destroy', () => {
      try { engine.destroy(); } catch (_) {}
      try { panel.destroy(); } catch (_) {}
      try { bubbleInteraction && bubbleInteraction.destroy && bubbleInteraction.destroy(); } catch (_) {}
      try { delete window.__MSG_WALL_LOADED__; } catch (_) {}
    });

    // 调试导出
    window.__MSG_WALL__ = { engine, provider, panel, bubbleInteraction, CONFIG };
    console.log('%c🐾 掘金消息墙已启动！', 'color:#1E80FF;font-size:14px;font-weight:bold;',
      '访问 window.__MSG_WALL__ 可调试。右上角面板可调节参数～');
  }

  // ========= 最小 Engine 兜底 =========
  function buildMinimalEngine() {
    class Eng {
      constructor(container, cfg) {
        this.container = container; this.config = cfg;
        this.canvas = document.createElement('canvas');
        this.canvas.style.cssText = 'position:fixed;left:0;top:0;width:100vw;height:100vh;pointer-events:none;z-index:'+cfg.zIndex+';';
        container.appendChild(this.canvas);
        this.ctx = this.canvas.getContext('2d');
        this.chars = [];
        this.running = false;
        const W = window.innerWidth, H = window.innerHeight;
        this.canvas.width = W; this.canvas.height = H;
        this.floorY = H * cfg.floorRatio;
        const CR = window.CharacterRenderer;
        for (let i = 0; i < cfg.characterCount; i++) {
          this.chars.push({
            x: Math.random() * W, y: this.floorY, type: 'person',
            dir: Math.random() < .5 ? 'left' : 'right',
            speed: .4 + Math.random()*.8, frame: 0, ft: 0,
            scale: 1 + Math.random()*.6,
            opts: CR.generateRandomOptions('person'),
            msg: null, msgTimer: 0,
          });
        }
        window.addEventListener('resize', () => {
          this.canvas.width = window.innerWidth;
          this.canvas.height = window.innerHeight;
          this.floorY = window.innerHeight * cfg.floorRatio;
        });
      }
      start(){
        this.running = true;
        let lastMsg = 0;
        const tick = () => {
          if (!this.running) return;
          const W = this.canvas.width, H = this.canvas.height;
          this.ctx.clearRect(0,0,W,H);
          this.chars.forEach(c => {
            c.x += c.dir==='right'? c.speed : -c.speed;
            if (c.x < 0) { c.x = 0; c.dir = 'right'; }
            if (c.x > W) { c.x = W; c.dir = 'left'; }
            c.ft++; if (c.ft > 6) { c.ft = 0; c.frame = (c.frame+1)%4; }
            c.y = this.floorY;
            CharacterRenderer.drawCharacter(this.ctx, c.x, c.y, c.type, c.dir, c.frame, c.scale, c.opts);
            if (c.msgTimer > 0) {
              c.msgTimer--;
              this.ctx.save();
              this.ctx.font = '12px sans-serif';
              const txt = (c.msg.text||'').slice(0,20);
              const tw = this.ctx.measureText(txt).width;
              this.ctx.fillStyle = '#fff';
              this.ctx.fillRect(c.x, c.y - 80, tw+16, 24);
              this.ctx.fillStyle = '#000';
              this.ctx.fillText(txt, c.x+8, c.y - 64);
              this.ctx.restore();
              if (c.msgTimer <= 0) c.msg = null;
            }
          });
          const now = Date.now();
          if (now - lastMsg > this.config.messageInterval) {
            lastMsg = now;
            if (typeof this.config.onMessageRequest === 'function') {
              const m = this.config.onMessageRequest();
              const idle = this.chars.filter(c => !c.msg);
              if (idle.length && m) {
                const t = idle[Math.floor(Math.random()*idle.length)];
                t.msg = m; t.msgTimer = 400;
              }
            }
          }
          requestAnimationFrame(tick);
        };
        tick();
      }
      stop(){ this.running = false; }
      destroy(){ this.running = false; if (this.canvas.parentNode) this.canvas.parentNode.removeChild(this.canvas); }
      updateConfig(c){ Object.assign(this.config, c); }
      setTypeRatio(){}
      pushMessage(text, meta){
        const idle = this.chars.filter(c => !c.msg);
        if (!idle.length) return;
        const t = idle[Math.floor(Math.random()*idle.length)];
        t.msg = {text, meta}; t.msgTimer = 400;
      }
      getCharacters(){ return this.chars.map(c => ({
        get message(){ return c.msg; }, set message(v){ c.msg = v; },
        get messageTimer(){ return c.msgTimer; }, set messageTimer(v){ c.msgTimer = v; },
        setMessage(t,m,d){ c.msg={text:t,meta:m}; c.msgTimer = Math.floor(d/16.67); },
        get type(){ return c.type; }, set type(v){ c.type = v; },
        get options(){ return c.opts; }, set options(v){ c.opts = v; },
        get x(){ return c.x; }, set x(v){ c.x = v; },
        get scale(){ return c.scale; }, set scale(v){ c.scale = v; },
      })); }
    }
    return { MessageWallEngine: Eng, Character: class{}, utils: {} };
  }

  function buildMinimalIntegration() {
    const DEMO = [
      '前端日常：今天又学到了新东西 ✨', '有大佬能帮忙看看这个问题吗？', '打卡第N天，加油加油！',
      '这篇文章写得太好了，点赞！', '新人报道，请多关照～', '求面试经验分享呀',
      '摸鱼时间到～😆', '这个CSS技巧真的好用', 'TS真香系列+1',
    ];
    class Prov {
      constructor(){ this.pool = []; }
      getMessageSync(){
        const txt = DEMO[Math.floor(Math.random()*DEMO.length)];
        return { text: txt, meta: { tagColor: '#1E80FF', source: '示例' } };
      }
      async getMessage(){ return this.getMessageSync(); }
      _ensurePoolFilled(){}
    }
    return {
      JuejinMessageProvider: Prov,
      ControlPanel: class {
        constructor(eng, prov, opt){
          this.eng = eng; this.prov = prov;
          const btn = document.createElement('button');
          btn.textContent = '🐾 掘金弹幕';
          Object.assign(btn.style, {
            position:'fixed', right: opt && opt.position && opt.position.includes('left') ? 'auto' : '16px',
            left: opt && opt.position && opt.position.includes('left') ? '16px' : 'auto',
            top:'16px', zIndex: 100000,
            padding: '8px 14px', borderRadius: '24px',
            border: 'none', cursor: 'pointer',
            background: 'linear-gradient(135deg,#1E80FF,#5B8DEF)',
            color: '#fff', fontWeight: '600',
            boxShadow: '0 4px 16px rgba(30,128,255,.4)',
          });
          btn.title = '点击暂停/继续';
          let running = true;
          btn.onclick = () => {
            running = !running;
            eng.updateConfig({ characterCount: running ? 16 : 0 });
            btn.textContent = running ? '🐾 运行中' : '🐾 已暂停';
          };
          document.body.appendChild(btn);
          this.btn = btn;
        }
        destroy(){ if (this.btn && this.btn.parentNode) this.btn.parentNode.removeChild(this.btn); }
      },
      CATEGORY_TAGS: {}
    };
  }

  // ========= Go! =========
  if (document.readyState === 'complete' || document.readyState === 'interactive') {
    setTimeout(boot, 300);
  } else {
    document.addEventListener('DOMContentLoaded', () => setTimeout(boot, 300));
  }
})();
